-- VFXForge weapon effects: client runtime
--
-- Generated by VFXForge. All tuning lives in config.lua; you normally never edit this file.
--
-- Design notes
--  * Particle assets are loaded once, lazily, on the first use, and released on resource stop.
--    A failed load is retried at most every Config.AssetRetryMs, on the next explicit trigger
--    (weapon change, test command, export) — so it recovers if the asset was merely late.
--  * There is NO unconditional per-frame loop: a slow poll (Config.IdlePollMs) watches for a
--    weapon change, and the per-frame loop only runs while a weapon listed in Config.Weapons
--    is actually selected.
--  * Every started particle is tracked; looped effects can never be started twice for the
--    same slot, and are stopped + removed on weapon switch, death and resource stop.
--  * Only documented natives are used. Natives that may not exist on every game build are
--    looked up through the global table first and guarded, so a missing one degrades instead
--    of throwing.

local RESOURCE <const> = GetCurrentResourceName()

local assetReady = false
local assetLoading = false
local assetFailedAt = nil -- GetGameTimer() of the last failed load; retries are rate limited

local selectedWeapon = 0
local weaponEntity = 0
local loops = {}      -- [effectIndex] = particle handle (looped effects currently alive)
local lastPlayed = {} -- [effectIndex] = GetGameTimer() of the last start (throttle)
local weaponSet = nil -- [hash] = true, or nil when every weapon is allowed

local function dbg(fmt, ...)
    if Config.Debug then
        print(('[%s] ' .. fmt):format(RESOURCE, ...))
    end
end

local function warn(fmt, ...)
    print(('^3[%s] ' .. fmt .. '^7'):format(RESOURCE, ...))
end

---------------------------------------------------------------------------
-- helpers
---------------------------------------------------------------------------

local function buildWeaponSet()
    if not Config.Weapons or #Config.Weapons == 0 then
        weaponSet = nil
        return
    end
    weaponSet = {}
    for _, name in ipairs(Config.Weapons) do
        weaponSet[GetHashKey(name)] = true
    end
end

local function isTracked(weaponHash)
    if weaponHash == 0 or weaponHash == GetHashKey('WEAPON_UNARMED') then
        return false
    end
    return weaponSet == nil or weaponSet[weaponHash] == true
end

local function hasTrigger(fx, name)
    for _, t in ipairs(fx.triggers) do
        if t == name then
            return true
        end
    end
    return false
end

--- Loads the particle asset. MUST be called from a thread (it yields).
local function ensureAsset()
    if assetReady then
        return true
    end
    if assetFailedAt and (GetGameTimer() - assetFailedAt) < Config.AssetRetryMs then
        return false -- failed recently: do not hammer the streaming system
    end
    if assetLoading then
        -- another thread is loading it: wait for that result instead of requesting again
        local deadline = GetGameTimer() + Config.AssetTimeoutMs
        while assetLoading and GetGameTimer() < deadline do
            Wait(10)
        end
        return assetReady
    end
    assetLoading = true
    RequestNamedPtfxAsset(Config.Asset)
    local deadline = GetGameTimer() + Config.AssetTimeoutMs
    while not HasNamedPtfxAssetLoaded(Config.Asset) do
        if GetGameTimer() > deadline then
            assetLoading = false
            assetFailedAt = GetGameTimer()
            warn('could not load particle asset "%s" within %d ms. Is %s/stream/%s.ypt present and started?',
                Config.Asset, Config.AssetTimeoutMs, RESOURCE, Config.Asset)
            return false
        end
        Wait(10)
    end
    assetLoading = false
    assetFailedAt = nil
    assetReady = true
    dbg('particle asset "%s" loaded', Config.Asset)
    return true
end

local function stopLoop(index)
    local handle = loops[index]
    if handle == nil then
        return
    end
    loops[index] = nil
    if DoesParticleFxLoopedExist(handle) then
        StopParticleFxLooped(handle, false)
        RemoveParticleFx(handle, false)
    end
    dbg('stopped looped effect #%d', index)
end

local function stopAllLoops()
    for index in pairs(loops) do
        stopLoop(index)
    end
end

---------------------------------------------------------------------------
-- starting effects
---------------------------------------------------------------------------

-- UseParticleFxAsset must be called immediately before EACH start call. Newer native databases
-- name it UseParticleFxAsset; older ones UseParticleFxAssetNextCall.
local function useAsset()
    local fn = UseParticleFxAsset or UseParticleFxAssetNextCall
    fn(Config.Asset)
end

local function boneIndexFor(entity, fx)
    if fx.bone == nil or fx.bone == '' then
        return -1
    end
    local idx = GetEntityBoneIndexByName(entity, fx.bone)
    if idx == nil or idx == -1 then
        dbg('bone "%s" not found on entity %d, falling back to the entity origin', fx.bone, entity)
        return -1
    end
    return idx
end

--- Starts effect `index` on `entity`. Returns the handle for looped effects, true for one-shots,
--- or nil when nothing was started. Safe to call from any context (does not yield).
local function startEffect(index, entity, looped)
    local fx = Config.Effects[index]
    if fx == nil or not assetReady or entity == nil or entity == 0 or not DoesEntityExist(entity) then
        return nil
    end
    local o, r = fx.offset, fx.rotation
    local bone = boneIndexFor(entity, fx)
    if looped then
        if loops[index] ~= nil and DoesParticleFxLoopedExist(loops[index]) then
            return loops[index] -- never duplicate a running loop
        end
        useAsset()
        local handle
        if bone ~= -1 and StartParticleFxLoopedOnEntityBone then
            handle = StartParticleFxLoopedOnEntityBone(fx.effect, entity, o.x, o.y, o.z, r.x, r.y, r.z, bone, fx.scale, false, false, false)
        else
            handle = StartParticleFxLoopedOnEntity(fx.effect, entity, o.x, o.y, o.z, r.x, r.y, r.z, fx.scale, false, false, false)
        end
        if handle ~= nil and handle ~= 0 and handle ~= -1 then
            loops[index] = handle
            if fx.color then
                SetParticleFxLoopedColour(handle, fx.color.r, fx.color.g, fx.color.b, false)
            end
            dbg('started looped effect #%d (%s)', index, fx.effect)
            return handle
        end
        return nil
    end

    -- one-shot: throttle so automatic weapons cannot flood the particle system
    local now = GetGameTimer()
    if fx.minIntervalMs and lastPlayed[index] and (now - lastPlayed[index]) < fx.minIntervalMs then
        return nil
    end
    lastPlayed[index] = now
    useAsset()
    if bone ~= -1 and GetWorldPositionOfEntityBone then
        -- there is no "on entity bone" one-shot native: spawn at the bone's current world position
        local p = GetWorldPositionOfEntityBone(entity, bone)
        StartParticleFxNonLoopedAtCoord(fx.effect, p.x + o.x, p.y + o.y, p.z + o.z, r.x, r.y, r.z, fx.scale, false, false, false)
    else
        StartParticleFxNonLoopedOnEntity(fx.effect, entity, o.x, o.y, o.z, r.x, r.y, r.z, fx.scale, false, false, false)
    end
    dbg('played effect #%d (%s)', index, fx.effect)
    return true
end

local function broadcast(index)
    if Config.Sync and Config.Sync.enabled then
        TriggerServerEvent(RESOURCE .. ':sync', index)
    end
end

--- Plays every effect bound to `trigger` for the local player's current weapon.
local function fireTrigger(trigger)
    local ped = PlayerPedId()
    if weaponEntity == 0 then
        weaponEntity = GetCurrentPedWeaponEntityIndex(ped)
    end
    for index, fx in ipairs(Config.Effects) do
        if hasTrigger(fx, trigger) then
            if startEffect(index, weaponEntity, fx.loop == true) then
                broadcast(index)
            end
        end
    end
end

---------------------------------------------------------------------------
-- weapon state machine
---------------------------------------------------------------------------

local function onWeaponChanged(ped, newWeapon)
    stopAllLoops() -- effects never outlive the weapon they belong to
    selectedWeapon = newWeapon
    weaponEntity = 0
    if not isTracked(newWeapon) then
        return
    end
    if not ensureAsset() then
        return
    end
    weaponEntity = GetCurrentPedWeaponEntityIndex(ped)
    -- the weapon model streams in a moment after the switch: wait (bounded) for the entity
    local deadline = GetGameTimer() + 1500
    while (weaponEntity == 0 or not DoesEntityExist(weaponEntity)) and GetGameTimer() < deadline do
        Wait(50)
        weaponEntity = GetCurrentPedWeaponEntityIndex(ped)
        if GetSelectedPedWeapon(ped) ~= newWeapon then
            return -- switched again while waiting; the main loop will handle the new weapon
        end
    end
    fireTrigger('switched')
    fireTrigger('equipped')
    fireTrigger('idle') -- idle effects are the looped ones (loop = true)
end

local function weaponLoop()
    local wasReloading = false
    while true do
        local ped = PlayerPedId()
        local weapon = GetSelectedPedWeapon(ped)
        if weapon ~= selectedWeapon then
            onWeaponChanged(ped, weapon)
        end
        if isTracked(weapon) and assetReady then
            if IsEntityDead(ped) then
                stopAllLoops()
                weaponEntity = 0
            else
                if IsPedShooting(ped) then
                    fireTrigger('fired')
                end
                local reloading = IsPedReloading(ped)
                if reloading and not wasReloading then
                    fireTrigger('reloaded')
                end
                wasReloading = reloading
                -- weapon entity respawned (e.g. after re-drawing): re-attach loops to the new entity
                local current = GetCurrentPedWeaponEntityIndex(ped)
                if current ~= 0 and current ~= weaponEntity then
                    stopAllLoops()
                    weaponEntity = current
                    fireTrigger('idle')
                end
            end
            Wait(0)
        else
            wasReloading = false
            Wait(Config.IdlePollMs)
        end
    end
end

---------------------------------------------------------------------------
-- network sync (optional): effects played by OTHER players
---------------------------------------------------------------------------

if Config.Sync and Config.Sync.enabled then
    RegisterNetEvent(RESOURCE .. ':play', function(sourceServerId, index)
        if type(index) ~= 'number' or Config.Effects[index] == nil then
            return
        end
        local player = GetPlayerFromServerId(sourceServerId)
        if player == -1 or player == PlayerId() then
            return
        end
        local otherPed = GetPlayerPed(player)
        if otherPed == 0 or not DoesEntityExist(otherPed) then
            return
        end
        local me = GetEntityCoords(PlayerPedId())
        local them = GetEntityCoords(otherPed)
        if #(me - them) > Config.Sync.radius then
            return
        end
        CreateThread(function()
            if not ensureAsset() then
                return
            end
            local entity = GetCurrentPedWeaponEntityIndex(otherPed)
            startEffect(index, entity, false)
        end)
    end)
end

---------------------------------------------------------------------------
-- developer test command + exports
---------------------------------------------------------------------------

if Config.EnableTestCommand then
    -- /<Config.TestCommand> [effectIndex|stop]  — plays the effect on your current weapon (or ped)
    RegisterCommand(Config.TestCommand, function(_, args)
        CreateThread(function()
            if args[1] == 'stop' then
                stopAllLoops()
                print(('[%s] stopped all looped effects'):format(RESOURCE))
                return
            end
            if not ensureAsset() then
                return
            end
            local ped = PlayerPedId()
            local entity = GetCurrentPedWeaponEntityIndex(ped)
            if entity == 0 then
                entity = ped -- unarmed: attach to the ped so you can still preview the effect
            end
            local only = tonumber(args[1])
            for index, fx in ipairs(Config.Effects) do
                if only == nil or only == index then
                    startEffect(index, entity, fx.loop == true)
                end
            end
            print(('[%s] test effect started (use "/%s stop" to end looped effects)'):format(RESOURCE, Config.TestCommand))
        end)
    end, false)
end

--- exports['<resource>']:PlayEffect(index) — trigger an effect from another script
exports('PlayEffect', function(index)
    local fx = Config.Effects[index]
    if fx == nil then
        return false
    end
    CreateThread(function()
        if ensureAsset() then
            local ped = PlayerPedId()
            local entity = GetCurrentPedWeaponEntityIndex(ped)
            startEffect(index, entity ~= 0 and entity or ped, fx.loop == true)
        end
    end)
    return true
end)

--- exports['<resource>']:StopEffects() — stop every looped effect started by this resource
exports('StopEffects', function()
    stopAllLoops()
end)

---------------------------------------------------------------------------
-- lifecycle
---------------------------------------------------------------------------

AddEventHandler('onResourceStop', function(resource)
    if resource ~= RESOURCE then
        return
    end
    stopAllLoops()
    if assetReady then
        RemoveNamedPtfxAsset(Config.Asset)
        assetReady = false
    end
end)

buildWeaponSet()
CreateThread(weaponLoop)
dbg('client ready (%d effect(s), asset "%s")', #Config.Effects, Config.Asset)
